class Solution {
    public int minStartValue(int[] nums) {
        int sum = 0;
        int minSum = Integer.MAX_VALUE;
        for (int n : nums) {
            sum += n;
            minSum = Math.min(minSum, sum);
        }
        if (minSum >= 0) return 1;
        return 1 - minSum;
    }
}
